    """int from ``[+-]?[0-9]+`` text, or None."""
    if not _SIGNED.fullmatch(token):
        return None
    return to_int(token)


def parse_sku(token):
    """Upper-cased SKU, or None when the shape is wrong."""
    if not _SKU.fullmatch(token):
        return None
    return ascii_upper(token)


def parse_order_id(token):
    """Upper-cased order id (digits kept as written), or None."""
    if not _ORDER_ID.fullmatch(token):
        return None
    return ascii_upper(token)


def parse_date(token):
    """datetime.date from ``YYYY-MM-DD`` text, or None (bad shape or not a real day)."""
    match = _DATE.fullmatch(token)
    if not match:
        return None
    try:
        return date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        return None
"""The orders: parsing, exact pricing, shipped quantities, fulfilment."""

from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal
from typing import List, Tuple

from .errors import ParseError
from .shelves import TAX_RATES, counting_order
from .textfile import (
    CTX,
    SEPARATOR,
    ZERO,
    content_lines,
    money,
    parse_date,
    parse_order_id,
    parse_sku,
    parse_unsigned,
)

VOLUME_TIERS = ((50, Decimal("0.10")), (10, Decimal("0.05")))
ORDER_DISCOUNT_THRESHOLD = Decimal("500.00")
ORDER_DISCOUNT_RATE = Decimal("0.03")


@dataclass
class Order:
    id: str
    date: date
    customer: str
    lines: List[Tuple[str, int]]
    line: int = field(default=0, compare=False)


@dataclass
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal
    order: str = ""
    date: date = None
    customer: str = ""


def parse_orders(text, catalog):
    """Parse ``orders.txt`` text into orders in the order written."""
    orders = []
    seen = set()
    for number, line in content_lines(text):
        fields = SEPARATOR.split(line)
        if len(fields) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES (4 fields)")
        order_id = parse_order_id(fields[0])
        if order_id is None:
            raise ParseError(
                number, "bad order number %r: expected SO- and digits" % fields[0]
            )
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        when = parse_date(fields[1])
        if when is None:
            raise ParseError(
                number, "bad date %r: expected a real YYYY-MM-DD date" % fields[1]
            )
        lines = []
        used = set()
        for item in fields[3].split(","):
            if item == "":
                raise ParseError(number, "empty item in the order lines")
            pair = item.split("*")
            if len(pair) != 2:
                raise ParseError(number, "bad order line %r: expected SKU*QUANTITY" % item)
            sku = parse_sku(pair[0])
            if sku is None or sku not in catalog:
                raise ParseError(number, "unknown SKU %r" % pair[0])
            if sku in used:
                raise ParseError(number, "SKU %s appears twice in the order" % sku)
            quantity = parse_unsigned(pair[1])
            if quantity is None or quantity < 1:
                raise ParseError(
                    number,
                    "bad quantity %r: expected a whole number of one or more" % pair[1],
                )
            used.add(sku)
            lines.append((sku, quantity))
        seen.add(order_id)
        orders.append(Order(order_id, when, fields[2], lines, number))
    return orders


def _pennies(amount):
    return int(amount.scaleb(2, context=CTX))


def _from_pennies(count):
    return money(Decimal(count).scaleb(-2, context=CTX))


def price_order(order, catalog, lines=None):
    """Price an order (or just ``lines``, a list of ``(sku, quantity)``) to the penny."""
    if lines is None:
        lines = order.lines
    gross_lines = []
    for sku, quantity in lines:
        unit = catalog[sku].price
        gross = money(CTX.multiply(Decimal(quantity), unit))
        rate = Decimal(0)
        for threshold, tier_rate in VOLUME_TIERS:
            if quantity >= threshold:
                rate = tier_rate
                break
        cut = money(CTX.multiply(gross, rate))
        discount = CTX.minus(cut) if cut else ZERO
        net = CTX.add(gross, discount)
        gross_lines.append((sku, quantity, unit, gross, discount, net))

    subtotal = ZERO
    for entry in gross_lines:
        subtotal = CTX.add(subtotal, entry[5])

    order_discount = ZERO
    if subtotal >= ORDER_DISCOUNT_THRESHOLD:
        order_discount = CTX.minus(money(CTX.multiply(subtotal, ORDER_DISCOUNT_RATE)))

    # Share the order discount out in whole pennies, largest remainder first.
    shares = [0] * len(gross_lines)
    owed = -_pennies(order_discount)
    if owed:
        total_net = _pennies(subtotal)
        remainders = []
        for index, entry in enumerate(gross_lines):
            product = owed * _pennies(entry[5])
            shares[index], rest = divmod(product, total_net)
            remainders.append((-rest, index))
        left = owed - sum(shares)
        remainders.sort()
        for _, index in remainders[:left]:
            shares[index] += 1

    quote_lines = []
    tax = ZERO
    for (sku, quantity, unit, gross, discount, net), share in zip(gross_lines, shares):
        quote_lines.append(QuoteLine(sku, quantity, unit, gross, discount, net))
        taxable = CTX.subtract(net, _from_pennies(share))
        rate = TAX_RATES[catalog[sku].tax]
        tax = CTX.add(tax, money(CTX.multiply(taxable, rate)))

    total = CTX.add(CTX.add(subtotal, order_discount), tax)
    return Quote(
        quote_lines,
        subtotal,
        order_discount,
        tax,
        total,
        getattr(order, "id", ""),
        getattr(order, "date", None),
        getattr(order, "customer", ""),
    )


def shipped_index(movements):
    """``{(SKU, note): units sent}`` over all negative movements."""
    index = {}
    for movement in movements:
        if movement.quantity < 0:
            key = (movement.sku, movement.note)
            index[key] = index.get(key, 0) - movement.quantity
    return index


def shipped_lines(order, index):
    """``[(sku, ordered, shipped)]`` for each order line; shipped is capped at ordered."""
    note = "order " + order.id
    return [
        (sku, quantity, min(quantity, index.get((sku, note), 0)))
        for sku, quantity in order.lines
    ]


def order_status(shipped, ordered):
    """``complete``, ``open`` or ``partial`` from per-line (shipped, ordered) totals."""
    if all(done >= wanted for done, wanted in zip(shipped, ordered)):
        return "complete"
    if not any(shipped):
        return "open"
    return "partial"


def plan_fulfilment(order, when, movements):
    """What to ship on ``when``: ``[(sku, ordered, shipped_before, ship_now)]``."""
    index = shipped_index(movements)
    counted = counting_order(movements)
    plan = []
    for sku, ordered, before in shipped_lines(order, index):
        balance = 0
        on_date = 0
        lowest_later = None
        for movement in counted:
            if movement.sku != sku:
                continue
            balance += movement.quantity
            if movement.date > when:
                if lowest_later is None or balance < lowest_later:
                    lowest_later = balance
            else:
                on_date = balance
        allowed = min(ordered - before, on_date)
        if lowest_later is not None:
            allowed = min(allowed, lowest_later)
        plan.append((sku, ordered, before, max(0, allowed)))
    return plan

"""The shelves: catalogue, movements, stock levels, low stock, history."""

import re
from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal

from .errors import ParseError
from .textfile import (
    ascii_lower,
    content_lines,
    parse_date,
    parse_price,
    parse_signed,
    parse_sku,
    parse_unsigned,
    trim,
)

TAX_RATES = {
    "standard": Decimal("0.20"),
    "reduced": Decimal("0.05"),
    "zero": Decimal("0"),
}

_MOVEMENT = re.compile(
    r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL
)


@dataclass
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"
    line: int = field(default=0, compare=False)


@dataclass
class Movement:
    date: date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False)


def parse_catalog(text):
    """Parse ``catalog.txt`` text into ``{SKU: Product}`` (file order)."""
    catalog = {}
    for number, line in content_lines(text):
        fields = [trim(part) for part in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number,
                "expected 4 or 5 fields separated by '|', found %d" % len(fields),
            )
        sku = parse_sku(fields[0])
        if sku is None:
            raise ParseError(
                number, "bad SKU %r: expected 2-4 letters, a dash and 3 digits" % fields[0]
            )
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        name = fields[1]
        if not name:
            raise ParseError(number, "the name is empty")
        price = parse_price(fields[2])
        if price is None:
            raise ParseError(
                number,
                "bad price %r: expected at least 0.01 with at most two decimals"
                % fields[2],
            )
        reorder = parse_unsigned(fields[3])
        if reorder is None:
            raise ParseError(
                number, "bad reorder level %r: expected a whole number" % fields[3]
            )
        tax = "standard"
        if len(fields) == 5:
            tax = ascii_lower(fields[4])
            if tax not in TAX_RATES:
                raise ParseError(
                    number,
                    "bad tax %r: expected standard, reduced or zero" % fields[4],
                )
        catalog[sku] = Product(sku, name, price, reorder, tax, number)
    return catalog


def counting_order(movements):
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda movement: movement.date)


def check_stock_rule(movements):
    """Raise ParseError at the first movement (in counting order) that takes stock below zero."""
    balance = {}
    for movement in counting_order(movements):
        total = balance.get(movement.sku, 0) + movement.quantity
        balance[movement.sku] = total
        if total < 0:
            raise ParseError(
                movement.line,
                "stock of %s would go below zero on %s"
                % (movement.sku, movement.date.isoformat()),
            )


def parse_movements(text, catalog):
    """Parse ``movements.txt`` text into movements in the order written."""
    movements = []
    for number, line in content_lines(text):
        match = _MOVEMENT.fullmatch(line)
        if not match:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        when = parse_date(match.group(1))
        if when is None:
            raise ParseError(
                number, "bad date %r: expected a real YYYY-MM-DD date" % match.group(1)
            )
        sku = parse_sku(match.group(2))
        if sku is None or sku not in catalog:
            raise ParseError(number, "unknown SKU %r" % match.group(2))
        quantity = parse_signed(match.group(3))
        if quantity is None:
            raise ParseError(
                number,
                "bad quantity %r: expected a whole number with an optional sign"
                % match.group(3),
            )
        if quantity == 0:
            raise ParseError(number, "the quantity is zero")
        note = trim(match.group(4) or "")
        movements.append(Movement(when, sku, quantity, note, number))
    check_stock_rule(movements)
    return movements


def stock_levels(catalog, movements):
    """``{SKU: on hand}`` for every product in the catalogue (sorted by SKU)."""
    levels = dict((sku, 0) for sku in sorted(catalog))
    for movement in movements:
        if movement.sku in levels:
            levels[movement.sku] += movement.quantity
    return levels


def stock_status(product, onhand):
    """``out``, ``low`` or ``ok``."""
    if onhand == 0:
        return "out"
    if onhand <= product.reorder:
        return "low"
    return "ok"


def buy_quantity(product, onhand):
    """How many to buy to get back to twice the reorder level (at least 1)."""
    return max(1, 2 * product.reorder - onhand)


def history(movements, sku):
    """``[(movement, balance_after)]`` for one SKU, in counting order."""
    balance = 0
    rows = []
    for movement in counting_order(movements):
        if movement.sku == sku:
            balance += movement.quantity
            rows.append((movement, balance))
    return rows
"""The ``stockroom`` command: argument handling, output and exit codes."""

import csv
import io
import json
import os
import sys

from .errors import ParseError
from .orders import (
    order_status,
    parse_orders,
    plan_fulfilment,
    price_order,
    shipped_index,
    shipped_lines,
)
from .shelves import (
    buy_quantity,
    history,
    parse_catalog,
    parse_movements,
    stock_levels,
    stock_status,
)
from .textfile import (
    ascii_upper,
    format_money,
    parse_date,
    parse_order_id,
    parse_sku,
    parse_unsigned,
)

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGUMENT ...]

commands:
  stock [--json]                          what is on the shelves
  low [--json]                            what to buy
  history SKU [--json]                    movements of one product
  receive DATE SKU QUANTITY [NOTE]        record stock in
  ship DATE SKU QUANTITY [NOTE]           record stock out
  quote ORDER [--json]                    price an order
  fulfil ORDER DATE                       ship what the shelves can cover
  invoice ORDER [--json]                  price what has shipped
  report [--format text|csv|json]         one row per order
"""

# command -> (fewest, most) positional arguments
ARITY = {
    "stock": (0, 0),
    "low": (0, 0),
    "report": (0, 0),
    "history": (1, 1),
    "quote": (1, 1),
    "invoice": (1, 1),
    "fulfil": (2, 2),
    "receive": (3, 4),
    "ship": (3, 4),
}
# commands whose arguments are all taken as typed (only --dir is an option)
AS_TYPED = ("receive", "ship", "fulfil")
JSON_COMMANDS = ("stock", "low", "history", "quote", "invoice")
FORMATS = ("text", "csv", "json")

# which data files each command reads
NEEDS = {
    "stock": ("catalog", "movements"),
    "low": ("catalog", "movements"),
    "history": ("catalog", "movements"),
    "receive": ("catalog", "movements"),
    "ship": ("catalog", "movements"),
    "quote": ("catalog", "orders"),
    "fulfil": ("catalog", "movements", "orders"),
    "invoice": ("catalog", "movements", "orders"),
    "report": ("catalog", "movements", "orders"),
}
FILENAMES = {
    "catalog": "catalog.txt",
    "movements": "movements.txt",
    "orders": "orders.txt",
}


class Fail(Exception):
    """Stop with an exit status and a message for standard error."""

    def __init__(self, code, message):
        Exception.__init__(self, message)
        self.code = code
        self.message = message


def usage_error(message):
    return Fail(2, "%s\n%s" % (message, USAGE.rstrip("\n")))


# ---------------------------------------------------------------- command line


class Request(object):
    def __init__(self):
        self.command = None
        self.directory = "."
        self.args = []
        self.json = False
        self.format = "text"


def parse_command_line(argv):
    # --dir DIR / --dir=DIR may stand anywhere, for every command.
    directory = None
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage_error("option --dir needs a folder")
            directory = argv[i + 1]
            i += 2
        elif arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
        else:
            rest.append(arg)
            i += 1
    if directory is not None and directory == "":
        raise usage_error("option --dir needs a folder")

    request = Request()
    if directory is not None:
        request.directory = directory

    position = None
    for index, arg in enumerate(rest):
        if not (arg.startswith("-") and len(arg) > 1):
            position = index
            break
    if position is None:
        if rest:
            raise usage_error("unknown option %s" % rest[0])
        raise usage_error("no command given")
    command = rest[position]
    if command not in ARITY:
        raise usage_error("unknown command %s" % command)
    request.command = command
    before, after = rest[:position], rest[position + 1:]

    if command in AS_TYPED:
        if before:
            raise usage_error("unknown option %s" % before[0])
        request.args = after
    else:
        tokens = before + after
        i = 0
        while i < len(tokens):
            token = tokens[i]
            i += 1
            if not (token.startswith("-") and len(token) > 1):
                request.args.append(token)
            elif token == "--json" and command in JSON_COMMANDS:
                request.json = True
            elif command == "report" and (
                token == "--format" or token.startswith("--format=")
            ):
                if token == "--format":
                    if i >= len(tokens):
                        raise usage_error("option --format needs a value")
                    value = tokens[i]
                    i += 1
                else:
                    value = token[len("--format="):]
                if value not in FORMATS:
                    raise usage_error(
                        "bad value %r for --format: expected text, csv or json" % value
                    )
                request.format = value
            else:
                raise usage_error("unknown option %s" % token)

    low, high = ARITY[command]
    if not low <= len(request.args) <= high:
        raise usage_error("wrong number of arguments for %s" % command)
    for arg in request.args:
        try:
            arg.encode("utf-8")
        except UnicodeEncodeError:
            raise usage_error("arguments must be valid UTF-8")
    if command in ("receive", "ship") and parse_date(request.args[0]) is None:
        raise usage_error("bad date %r: expected a real YYYY-MM-DD date" % request.args[0])
    if command == "fulfil" and parse_date(request.args[1]) is None:
        raise usage_error("bad date %r: expected a real YYYY-MM-DD date" % request.args[1])
    return request


# ----------------------------------------------------------------------- files


def read_inputs(request):
    """Return ``{kind: (raw_bytes, text)}`` for the files the command needs."""
    if not os.path.isdir(request.directory):
        raise Fail(2, "%s: not a folder that exists" % request.directory)
    inputs = {}
    for kind in NEEDS[request.command]:
        name = FILENAMES[kind]
        path = os.path.join(request.directory, name)
        try:
            with open(path, "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            if kind == "catalog":
                raise Fail(2, "%s: file not found" % name)
            raw = b""
        except OSError as error:
            raise Fail(2, "%s: cannot be read (%s)" % (name, error.strerror or error))
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise Fail(2, "%s: not valid UTF-8" % name)
        inputs[kind] = (raw, text)
    return inputs


def parsed(name, function, *args):
    try:
        return function(*args)
    except ParseError as error:
        raise Fail(1, "%s: %s" % (name, error))


class Data(object):
    """Parsed files for one run."""

    def __init__(self, request):
        self.directory = request.directory
        inputs = read_inputs(request)
        self.inputs = inputs
        self.catalog = parsed("catalog.txt", parse_catalog, inputs["catalog"][1])
        self.movements = None
        self.orders = None
        if "movements" in inputs:
            self.movements = parsed(
                "movements.txt", parse_movements, inputs["movements"][1], self.catalog
            )
        if "orders" in inputs:
            self.orders = parsed(
                "orders.txt", parse_orders, inputs["orders"][1], self.catalog
            )

    def find_order(self, token):
        order_id = parse_order_id(token)
        for order in self.orders:
            if order.id == order_id:
                return order
        raise Fail(1, "unknown order %s" % token)

    def append_movements(self, new_lines):
        """Append lines to movements.txt after re-checking the whole would-be file."""
        raw, text = self.inputs["movements"]
        prefix = "\n" if raw and not raw.endswith(b"\n") else ""
        addition = prefix + "".join(line + "\n" for line in new_lines)
        parsed("movements.txt", parse_movements, text + addition, self.catalog)
        path = os.path.join(self.directory, FILENAMES["movements"])
        try:
            with open(path, "ab") as handle:
                handle.write(addition.encode("utf-8"))
        except OSError as error:
            raise Fail(
                2, "movements.txt: cannot be written (%s)" % (error.strerror or error)
            )


# ------------------------------------------------------------------- rendering


def dump_json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def signed(number):
    return ("+" if number > 0 else "") + str(number)


def render_quote(quote, json_mode, prefix=""):
    if json_mode:
        return dump_json(
            {
                "order": quote.order,
                "date": quote.date.isoformat(),
                "customer": quote.customer,
                "lines": [
                    {
                        "sku": line.sku,
                        "quantity": line.quantity,
                        "unit": format_money(line.unit),
                        "gross": format_money(line.gross),
                        "discount": format_money(line.discount),
                        "net": format_money(line.net),
                    }
                    for line in quote.lines
                ],
                "subtotal": format_money(quote.subtotal),
                "order_discount": format_money(quote.order_discount),
                "tax": format_money(quote.tax),
                "total": format_money(quote.total),
            }
        )
    out = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(), quote.customer)]
    for line in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (
                line.sku,
                line.quantity,
                format_money(line.unit),
                format_money(line.gross),
                format_money(line.discount),
                format_money(line.net),
            )
        )
    out.append("subtotal " + format_money(quote.subtotal))
    out.append("order discount " + format_money(quote.order_discount))
    out.append("tax " + format_money(quote.tax))
    out.append("total " + format_money(quote.total))
    return "\n".join(out) + "\n"


def lines_out(lines):
    return "".join(line + "\n" for line in lines)


# -------------------------------------------------------------------- commands


def cmd_stock(request, data):
    levels = stock_levels(data.catalog, data.movements)
    rows = [
        (sku, data.catalog[sku], onhand, stock_status(data.catalog[sku], onhand))
        for sku, onhand in levels.items()
    ]
    if request.json:
        return dump_json(
            [
                {"sku": sku, "name": product.name, "onhand": onhand, "status": status}
                for sku, product, onhand, status in rows
            ]
        )
    return lines_out(
        "%s %d %s %s" % (sku, onhand, status, product.name)
        for sku, product, onhand, status in rows
    )


def cmd_low(request, data):
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku, onhand in levels.items():
        product = data.catalog[sku]
        if stock_status(product, onhand) != "ok":
            rows.append((sku, onhand, product.reorder, buy_quantity(product, onhand)))
    if request.json:
        return dump_json(
            [
                {"sku": sku, "onhand": onhand, "reorder": reorder, "buy": buy}
                for sku, onhand, reorder, buy in rows
            ]
        )
    return lines_out("%s %d %d %d" % row for row in rows)


def cmd_history(request, data):
    sku = ascii_upper(request.args[0])
    if sku not in data.catalog:
        raise Fail(1, "unknown SKU %s" % request.args[0])
    rows = history(data.movements, sku)
    if request.json:
        return dump_json(
            [
                {
                    "date": move.date.isoformat(),
                    "delta": signed(move.quantity),
                    "balance": balance,
                    "note": move.note,
                }
                for move, balance in rows
            ]
        )
    out = []
    for move, balance in rows:
        line = "%s %s %d" % (move.date.isoformat(), signed(move.quantity), balance)
        if move.note:
            line += " " + move.note
        out.append(line)
    return lines_out(out)


def movement_line(date_text, sku, delta, note):
    line = "%s %s %s" % (date_text, sku, delta)
    if note:
        line += " " + note
    return line


def cmd_move(request, data):
    date_text, sku_text, quantity_text = request.args[:3]
    note = request.args[3].strip(" \t") if len(request.args) == 4 else ""
    sku = ascii_upper(sku_text)
    if parse_sku(sku_text) is None or sku not in data.catalog:
        raise Fail(1, "unknown SKU %s" % sku_text)
    quantity = parse_unsigned(quantity_text)
    if quantity is None or quantity < 1:
        raise Fail(
            1, "bad quantity %r: expected a whole number of one or more" % quantity_text
        )
    if "\n" in note or "\r" in note:
        raise Fail(1, "the note may not contain a line break")
    sign = "+" if request.command == "receive" else "-"
    line = movement_line(date_text, sku, sign + str(quantity), note)
    data.append_movements([line])
    return line + "\n"


def cmd_quote(request, data):
    order = data.find_order(request.args[0])
    return render_quote(price_order(order, data.catalog), request.json)


def cmd_fulfil(request, data):
    order = data.find_order(request.args[0])
    when = parse_date(request.args[1])
    if when < order.date:
        raise Fail(
            1,
            "cannot fulfil %s on %s: before the order date %s"
            % (order.id, when.isoformat(), order.date.isoformat()),
        )
    plan = plan_fulfilment(order, when, data.movements)
    new_lines = [
        movement_line(request.args[1], sku, "-%d" % now, "order " + order.id)
        for sku, _, _, now in plan
        if now > 0
    ]
    if new_lines:
        data.append_movements(new_lines)
    out = []
    shipped, ordered = [], []
    for sku, wanted, before, now in plan:
        out.append("%s shipped %d backordered %d" % (sku, now, wanted - before - now))
        shipped.append(before + now)
        ordered.append(wanted)
    out.append("status " + order_status(shipped, ordered))
    return lines_out(out)


def cmd_invoice(request, data):
    order = data.find_order(request.args[0])
    index = shipped_index(data.movements)
    lines = [
        (sku, done) for sku, _, done in shipped_lines(order, index) if done > 0
    ]
    if not lines:
        raise Fail(1, "nothing has shipped on %s yet" % order.id)
    quote = price_order(order, data.catalog, lines)
    return render_quote(quote, request.json, "invoice ")


def order_sort_key(order):
    digits = order.id[3:].lstrip("0")  # numeric order without converting huge numbers
    return (order.date, len(digits), digits, order.id)


def cmd_report(request, data):
    index = shipped_index(data.movements)
    rows = []
    for order in sorted(data.orders, key=order_sort_key):
        per_line = shipped_lines(order, index)
        ordered = sum(wanted for _, wanted, _ in per_line)
        shipped = sum(done for _, _, done in per_line)
        status = order_status([d for _, _, d in per_line], [w for _, w, _ in per_line])
        quoted = price_order(order, data.catalog).total
        sent = [(sku, done) for sku, _, done in per_line if done > 0]
        invoiced = price_order(order, data.catalog, sent).total if sent else None
        rows.append(
            (
                order,
                status,
                ordered,
                shipped,
                format_money(quoted),
                format_money(invoiced) if invoiced is not None else "0.00",
            )
        )
    if request.format == "json":
        return dump_json(
            [
                {
                    "order": order.id,
                    "date": order.date.isoformat(),
                    "customer": order.customer,
                    "status": status,
                    "ordered": ordered,
                    "shipped": shipped,
                    "quoted": quoted,
                    "invoiced": invoiced,
                }
                for order, status, ordered, shipped, quoted, invoiced in rows
            ]
        )
    if request.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(
            ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        )
        for order, status, ordered, shipped, quoted, invoiced in rows:
            writer.writerow(
                [order.id, order.date.isoformat(), order.customer, status,
                 ordered, shipped, quoted, invoiced]
            )
        return buffer.getvalue()
    return lines_out(
        "%s %s %s %s %d/%d %s %s"
        % (order.id, order.date.isoformat(), order.customer, status,
           shipped, ordered, quoted, invoiced)
        for order, status, ordered, shipped, quoted, invoiced in rows
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# ------------------------------------------------------------------------ main


def _write(stream, text):
    data = text.encode("utf-8", "replace")
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        buffer.write(data)
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout():
    try:
        target = os.open(os.devnull, os.O_WRONLY)
        os.dup2(target, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass


def _report_failure(message):
    try:
        _write(sys.stderr, "stockroom: %s\n" % message)
    except Exception:
        pass


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)
    try:
        request = parse_command_line(list(argv))
        output = HANDLERS[request.command](request, Data(request))
    except Fail as failure:
        _report_failure(failure.message)
        return failure.code
    if not output:
        return 0
    try:
        _write(sys.stdout, output)
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except OSError as error:
        _silence_stdout()
        _report_failure("cannot write output (%s)" % (error.strerror or error))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""The shelves: catalogue, movements, stock levels, low stock, history."""

import re
from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal

from .errors import ParseError
from .textfile import (
    ascii_lower,
    content_lines,
    parse_date,
    parse_price,
    parse_signed,
    parse_sku,
    parse_unsigned,
    trim,
)

TAX_RATES = {
    "standard": Decimal("0.20"),
    "reduced": Decimal("0.05"),
    "zero": Decimal("0"),
}

_MOVEMENT = re.compile(
    r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL
)


@dataclass
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"
    line: int = field(default=0, compare=False)


@dataclass
class Movement:
    date: date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False)


def parse_catalog(text):
    """Parse ``catalog.txt`` text into ``{SKU: Product}`` (file order)."""
    catalog = {}
    for number, line in content_lines(text):
        fields = [trim(part) for part in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number,
                "expected 4 or 5 fields separated by '|', found %d" % len(fields),
            )
        sku = parse_sku(fields[0])
        if sku is None:
            raise ParseError(
                number, "bad SKU %r: expected 2-4 letters, a dash and 3 digits" % fields[0]
            )
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        name = fields[1]
        if not name:
            raise ParseError(number, "the name is empty")
        price = parse_price(fields[2])
        if price is None:
            raise ParseError(
                number,
                "bad price %r: expected at least 0.01 with at most two decimals"
                % fields[2],
            )
        reorder = parse_unsigned(fields[3])
        if reorder is None:
            raise ParseError(
                number, "bad reorder level %r: expected a whole number" % fields[3]
            )
        tax = "standard"
        if len(fields) == 5:
            tax = ascii_lower(fields[4])
            if tax not in TAX_RATES:
                raise ParseError(
                    number,
                    "bad tax %r: expected standard, reduced or zero" % fields[4],
                )
        catalog[sku] = Product(sku, name, price, reorder, tax, number)
    return catalog


def counting_order(movements):
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda movement: movement.date)


def check_stock_rule(movements):
    """Raise ParseError at the first movement (in counting order) that takes stock below zero."""
    balance = {}
    for movement in counting_order(movements):
        total = balance.get(movement.sku, 0) + movement.quantity
        balance[movement.sku] = total
        if total < 0:
            raise ParseError(
                movement.line,
                "stock of %s would go below zero on %s"
                % (movement.sku, movement.date.isoformat()),
            )


def parse_movements(text, catalog):
    """Parse ``movements.txt`` text into movements in the order written."""
    movements = []
    for number, line in content_lines(text):
        match = _MOVEMENT.fullmatch(line)
        if not match:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        when = parse_date(match.group(1))
        if when is None:
            raise ParseError(
                number, "bad date %r: expected a real YYYY-MM-DD date" % match.group(1)
            )
        sku = parse_sku(match.group(2))
        if sku is None or sku not in catalog:
            raise ParseError(number, "unknown SKU %r" % match.group(2))
        quantity = parse_signed(match.group(3))
        if quantity is None:
            raise ParseError(
                number,
                "bad quantity %r: expected a whole number with an optional sign"
                % match.group(3),
            )
        if quantity == 0:
            raise ParseError(number, "the quantity is zero")
        note = trim(match.group(4) or "")
        movements.append(Movement(when, sku, quantity, note, number))
    check_stock_rule(movements)
    return movements


def stock_levels(catalog, movements):
    """``{SKU: on hand}`` for every product in the catalogue (sorted by SKU)."""
    levels = dict((sku, 0) for sku in sorted(catalog))
    for movement in movements:
        if movement.sku in levels:
            levels[movement.sku] += movement.quantity
    return levels


def stock_status(product, onhand):
    """``out``, ``low`` or ``ok``."""
    if onhand == 0:
        return "out"
    if onhand <= product.reorder:
        return "low"
    return "ok"


def buy_quantity(product, onhand):
    """How many to buy to get back to twice the reorder level (at least 1)."""
    return max(1, 2 * product.reorder - onhand)


def history(movements, sku):
    """``[(movement, balance_after)]`` for one SKU, in counting order."""
    balance = 0
    rows = []
    for movement in counting_order(movements):
        if movement.sku == sku:
            balance += movement.quantity
            rows.append((movement, balance))
    return rows
"""The ``stockroom`` command: argument handling, output and exit codes."""

import csv
import io
import json
import os
import sys

from .errors import ParseError
from .orders import (
    order_status,
    parse_orders,
    plan_fulfilment,
    price_order,
    shipped_index,
    shipped_lines,
)
from .shelves import (
    buy_quantity,
    history,
    parse_catalog,
    parse_movements,
    stock_levels,
    stock_status,
)
from .textfile import (
    ascii_upper,
    format_money,
    parse_date,
    parse_order_id,
    parse_sku,
    parse_unsigned,
)

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGUMENT ...]

commands:
  stock [--json]                          what is on the shelves
  low [--json]                            what to buy
  history SKU [--json]                    movements of one product
  receive DATE SKU QUANTITY [NOTE]        record stock in
  ship DATE SKU QUANTITY [NOTE]           record stock out
  quote ORDER [--json]                    price an order
  fulfil ORDER DATE                       ship what the shelves can cover
  invoice ORDER [--json]                  price what has shipped
  report [--format text|csv|json]         one row per order
"""

# command -> (fewest, most) positional arguments
ARITY = {
    "stock": (0, 0),
    "low": (0, 0),
    "report": (0, 0),
    "history": (1, 1),
    "quote": (1, 1),
    "invoice": (1, 1),
    "fulfil": (2, 2),
    "receive": (3, 4),
    "ship": (3, 4),
}
# commands whose arguments are all taken as typed (only --dir is an option)
AS_TYPED = ("receive", "ship", "fulfil")
JSON_COMMANDS = ("stock", "low", "history", "quote", "invoice")
FORMATS = ("text", "csv", "json")

# which data files each command reads
NEEDS = {
    "stock": ("catalog", "movements"),
    "low": ("catalog", "movements"),
    "history": ("catalog", "movements"),
    "receive": ("catalog", "movements"),
    "ship": ("catalog", "movements"),
    "quote": ("catalog", "orders"),
    "fulfil": ("catalog", "movements", "orders"),
    "invoice": ("catalog", "movements", "orders"),
    "report": ("catalog", "movements", "orders"),
}
FILENAMES = {
    "catalog": "catalog.txt",
    "movements": "movements.txt",
    "orders": "orders.txt",
}


class Fail(Exception):
    """Stop with an exit status and a message for standard error."""

    def __init__(self, code, message):
        Exception.__init__(self, message)
        self.code = code
        self.message = message


def usage_error(message):
    return Fail(2, "%s\n%s" % (message, USAGE.rstrip("\n")))


# ---------------------------------------------------------------- command line


class Request(object):
    def __init__(self):
        self.command = None
        self.directory = "."
        self.args = []
        self.json = False
        self.format = "text"


def parse_command_line(argv):
    # --dir DIR / --dir=DIR may stand anywhere, for every command.
    directory = None
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage_error("option --dir needs a folder")
            directory = argv[i + 1]
            i += 2
        elif arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
        else:
            rest.append(arg)
            i += 1
    if directory is not None and directory == "":
        raise usage_error("option --dir needs a folder")

    request = Request()
    if directory is not None:
        request.directory = directory

    position = None
    for index, arg in enumerate(rest):
        if not (arg.startswith("-") and len(arg) > 1):
            position = index
            break
    if position is None:
        if rest:
            raise usage_error("unknown option %s" % rest[0])
        raise usage_error("no command given")
    command = rest[position]
    if command not in ARITY:
        raise usage_error("unknown command %s" % command)
    request.command = command
    before, after = rest[:position], rest[position + 1:]

    if command in AS_TYPED:
        if before:
            raise usage_error("unknown option %s" % before[0])
        request.args = after
    else:
        tokens = before + after
        i = 0
        while i < len(tokens):
            token = tokens[i]
            i += 1
            if not (token.startswith("-") and len(token) > 1):
                request.args.append(token)
            elif token == "--json" and command in JSON_COMMANDS:
                request.json = True
            elif command == "report" and (
                token == "--format" or token.startswith("--format=")
            ):
                if token == "--format":
                    if i >= len(tokens):
                        raise usage_error("option --format needs a value")
                    value = tokens[i]
                    i += 1
                else:
                    value = token[len("--format="):]
                if value not in FORMATS:
                    raise usage_error(
                        "bad value %r for --format: expected text, csv or json" % value
                    )
                request.format = value
            else:
                raise usage_error("unknown option %s" % token)

    low, high = ARITY[command]
    if not low <= len(request.args) <= high:
        raise usage_error("wrong number of arguments for %s" % command)
    for arg in request.args:
        try:
            arg.encode("utf-8")
        except UnicodeEncodeError:
            raise usage_error("arguments must be valid UTF-8")
    if command in ("receive", "ship") and parse_date(request.args[0]) is None:
        raise usage_error("bad date %r: expected a real YYYY-MM-DD date" % request.args[0])
    if command == "fulfil" and parse_date(request.args[1]) is None:
        raise usage_error("bad date %r: expected a real YYYY-MM-DD date" % request.args[1])
    return request


# ----------------------------------------------------------------------- files


def read_inputs(request):
    """Return ``{kind: (raw_bytes, text)}`` for the files the command needs."""
    if not os.path.isdir(request.directory):
        raise Fail(2, "%s: not a folder that exists" % request.directory)
    inputs = {}
    for kind in NEEDS[request.command]:
        name = FILENAMES[kind]
        path = os.path.join(request.directory, name)
        try:
            with open(path, "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            if kind == "catalog":
                raise Fail(2, "%s: file not found" % name)
            raw = b""
        except OSError as error:
            raise Fail(2, "%s: cannot be read (%s)" % (name, error.strerror or error))
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise Fail(2, "%s: not valid UTF-8" % name)
        inputs[kind] = (raw, text)
    return inputs


def parsed(name, function, *args):
    try:
        return function(*args)
    except ParseError as error:
        raise Fail(1, "%s: %s" % (name, error))


class Data(object):
    """Parsed files for one run."""

    def __init__(self, request):
        self.directory = request.directory
        inputs = read_inputs(request)
        self.inputs = inputs
        self.catalog = parsed("catalog.txt", parse_catalog, inputs["catalog"][1])
        self.movements = None
        self.orders = None
        if "movements" in inputs:
            self.movements = parsed(
                "movements.txt", parse_movements, inputs["movements"][1], self.catalog
            )
        if "orders" in inputs:
            self.orders = parsed(
                "orders.txt", parse_orders, inputs["orders"][1], self.catalog
            )

    def find_order(self, token):
        order_id = parse_order_id(token)
        for order in self.orders:
            if order.id == order_id:
                return order
        raise Fail(1, "unknown order %s" % token)

    def append_movements(self, new_lines):
        """Append lines to movements.txt after re-checking the whole would-be file."""
        raw, text = self.inputs["movements"]
        prefix = "\n" if raw and not raw.endswith(b"\n") else ""
        addition = prefix + "".join(line + "\n" for line in new_lines)
        parsed("movements.txt", parse_movements, text + addition, self.catalog)
        path = os.path.join(self.directory, FILENAMES["movements"])
        try:
            with open(path, "ab") as handle:
                handle.write(addition.encode("utf-8"))
        except OSError as error:
            raise Fail(
                2, "movements.txt: cannot be written (%s)" % (error.strerror or error)
            )


# ------------------------------------------------------------------- rendering


def dump_json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def signed(number):
    return ("+" if number > 0 else "") + str(number)


def render_quote(quote, json_mode, prefix=""):
    if json_mode:
        return dump_json(
            {
                "order": quote.order,
                "date": quote.date.isoformat(),
                "customer": quote.customer,
                "lines": [
                    {
                        "sku": line.sku,
                        "quantity": line.quantity,
                        "unit": format_money(line.unit),
                        "gross": format_money(line.gross),
                        "discount": format_money(line.discount),
                        "net": format_money(line.net),
                    }
                    for line in quote.lines
                ],
                "subtotal": format_money(quote.subtotal),
                "order_discount": format_money(quote.order_discount),
                "tax": format_money(quote.tax),
                "total": format_money(quote.total),
            }
        )
    out = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(), quote.customer)]
    for line in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (
                line.sku,
                line.quantity,
                format_money(line.unit),
                format_money(line.gross),
                format_money(line.discount),
                format_money(line.net),
            )
        )
    out.append("subtotal " + format_money(quote.subtotal))
    out.append("order discount " + format_money(quote.order_discount))
    out.append("tax " + format_money(quote.tax))
    out.append("total " + format_money(quote.total))
    return "\n".join(out) + "\n"


def lines_out(lines):
    return "".join(line + "\n" for line in lines)


# -------------------------------------------------------------------- commands


def cmd_stock(request, data):
    levels = stock_levels(data.catalog, data.movements)
    rows = [
        (sku, data.catalog[sku], onhand, stock_status(data.catalog[sku], onhand))
        for sku, onhand in levels.items()
    ]
    if request.json:
        return dump_json(
            [
                {"sku": sku, "name": product.name, "onhand": onhand, "status": status}
                for sku, product, onhand, status in rows
            ]
        )
    return lines_out(
        "%s %d %s %s" % (sku, onhand, status, product.name)
        for sku, product, onhand, status in rows
    )


def cmd_low(request, data):
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku, onhand in levels.items():
        product = data.catalog[sku]
        if stock_status(product, onhand) != "ok":
            rows.append((sku, onhand, product.reorder, buy_quantity(product, onhand)))
    if request.json:
        return dump_json(
            [
                {"sku": sku, "onhand": onhand, "reorder": reorder, "buy": buy}
                for sku, onhand, reorder, buy in rows
            ]
        )
    return lines_out("%s %d %d %d" % row for row in rows)


def cmd_history(request, data):
    sku = ascii_upper(request.args[0])
    if sku not in data.catalog:
        raise Fail(1, "unknown SKU %s" % request.args[0])
    rows = history(data.movements, sku)
    if request.json:
        return dump_json(
            [
                {
                    "date": move.date.isoformat(),
                    "delta": signed(move.quantity),
                    "balance": balance,
                    "note": move.note,
                }
                for move, balance in rows
            ]
        )
    out = []
    for move, balance in rows:
        line = "%s %s %d" % (move.date.isoformat(), signed(move.quantity), balance)
        if move.note:
            line += " " + move.note
        out.append(line)
    return lines_out(out)


def movement_line(date_text, sku, delta, note):
    line = "%s %s %s" % (date_text, sku, delta)
    if note:
        line += " " + note
    return line


def cmd_move(request, data):
    date_text, sku_text, quantity_text = request.args[:3]
    note = request.args[3].strip(" \t") if len(request.args) == 4 else ""
    sku = ascii_upper(sku_text)
    if parse_sku(sku_text) is None or sku not in data.catalog:
        raise Fail(1, "unknown SKU %s" % sku_text)
    quantity = parse_unsigned(quantity_text)
    if quantity is None or quantity < 1:
        raise Fail(
            1, "bad quantity %r: expected a whole number of one or more" % quantity_text
        )
    if "\n" in note or "\r" in note:
        raise Fail(1, "the note may not contain a line break")
    sign = "+" if request.command == "receive" else "-"
    line = movement_line(date_text, sku, sign + str(quantity), note)
    data.append_movements([line])
    return line + "\n"


def cmd_quote(request, data):
    order = data.find_order(request.args[0])
    return render_quote(price_order(order, data.catalog), request.json)


def cmd_fulfil(request, data):
    order = data.find_order(request.args[0])
    when = parse_date(request.args[1])
    if when < order.date:
        raise Fail(
            1,
            "cannot fulfil %s on %s: before the order date %s"
            % (order.id, when.isoformat(), order.date.isoformat()),
        )
    plan = plan_fulfilment(order, when, data.movements)
    new_lines = [
        movement_line(request.args[1], sku, "-%d" % now, "order " + order.id)
        for sku, _, _, now in plan
        if now > 0
    ]
    if new_lines:
        data.append_movements(new_lines)
    out = []
    shipped, ordered = [], []
    for sku, wanted, before, now in plan:
        out.append("%s shipped %d backordered %d" % (sku, now, wanted - before - now))
        shipped.append(before + now)
        ordered.append(wanted)
    out.append("status " + order_status(shipped, ordered))
    return lines_out(out)


def cmd_invoice(request, data):
    order = data.find_order(request.args[0])
    index = shipped_index(data.movements)
    lines = [
        (sku, done) for sku, _, done in shipped_lines(order, index) if done > 0
    ]
    if not lines:
        raise Fail(1, "nothing has shipped on %s yet" % order.id)
    quote = price_order(order, data.catalog, lines)
    return render_quote(quote, request.json, "invoice ")


def order_sort_key(order):
    digits = order.id[3:].lstrip("0")  # numeric order without converting huge numbers
    return (order.date, len(digits), digits, order.id)


def cmd_report(request, data):
    index = shipped_index(data.movements)
    rows = []
    for order in sorted(data.orders, key=order_sort_key):
        per_line = shipped_lines(order, index)
        ordered = sum(wanted for _, wanted, _ in per_line)
        shipped = sum(done for _, _, done in per_line)
        status = order_status([d for _, _, d in per_line], [w for _, w, _ in per_line])
        quoted = price_order(order, data.catalog).total
        sent = [(sku, done) for sku, _, done in per_line if done > 0]
        invoiced = price_order(order, data.catalog, sent).total if sent else None
        rows.append(
            (
                order,
                status,
                ordered,
                shipped,
                format_money(quoted),
                format_money(invoiced) if invoiced is not None else "0.00",
            )
        )
    if request.format == "json":
        return dump_json(
            [
                {
                    "order": order.id,
                    "date": order.date.isoformat(),
                    "customer": order.customer,
                    "status": status,
                    "ordered": ordered,
                    "shipped": shipped,
                    "quoted": quoted,
                    "invoiced": invoiced,
                }
                for order, status, ordered, shipped, quoted, invoiced in rows
            ]
        )
    if request.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(
            ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        )
        for order, status, ordered, shipped, quoted, invoiced in rows:
            writer.writerow(
                [order.id, order.date.isoformat(), order.customer, status,
                 ordered, shipped, quoted, invoiced]
            )
        return buffer.getvalue()
    return lines_out(
        "%s %s %s %s %d/%d %s %s"
        % (order.id, order.date.isoformat(), order.customer, status,
           shipped, ordered, quoted, invoiced)
        for order, status, ordered, shipped, quoted, invoiced in rows
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# ------------------------------------------------------------------------ main


def _write(stream, text):
    data = text.encode("utf-8", "replace")
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        buffer.write(data)
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _silence_stdout():
    try:
        target = os.open(os.devnull, os.O_WRONLY)
        os.dup2(target, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass


def _report_failure(message):
    try:
        _write(sys.stderr, "stockroom: %s\n" % message)
    except Exception:
        pass


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)
    try:
        request = parse_command_line(list(argv))
        output = HANDLERS[request.command](request, Data(request))
    except Fail as failure:
        _report_failure(failure.message)
        return failure.code
    if not output:
        return 0
    try:
        _write(sys.stdout, output)
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except OSError as error:
        _silence_stdout()
        _report_failure("cannot write output (%s)" % (error.strerror or error))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

